export function TabNav(t,a){return`<div class="education-tab-nav" role="tablist">\n    <div class="tab-scroll">${t.map(t=>{const n=t.id===a;return`<button class="education-tab-btn ${n?"active":""}"\n        data-tab="${t.id}"\n        role="tab"\n        aria-selected="${n}"\n        tabindex="${n?0:-1}">\n        ${t.label}\n      </button>`}).join("")}</div>\n  </div>`}